INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(24001, 'Luke 5:21', 'Luke', 5, 21, '&nbsp;نو د شرعې عالمانو او فريسيانو يو بل ته ووئيل چې، ”دا څوک دے چې کُفر وائى؟ د خُدائ پاک نه بغېر هم لا څوک د چا ګناهونه بخښلے شى څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24002, 'Luke 5:22', 'Luke', 5, 22, '&nbsp;خو عيسىٰ د دوئ په خيال پوهه وو چې دوئ څۀ خيال کوى نو جواب يې ورکړو چې، ”تاسو په خپلو زړونو کښې داسې خيالونه ولې راولئ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24003, 'Luke 5:23', 'Luke', 5, 23, '&nbsp;آيا دا آسانه خبره ده چې ووائى چې ګناهونه دې معاف شُو، او کۀ دا چې ووائى چې پاڅه او وګرځه؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24004, 'Luke 5:24', 'Luke', 5, 24, '&nbsp;خو دا ځکه چې تاسو په دې پوهه شئ چې اِبن آدم سره په دُنيا کښې د ګناهونو د بخښلو اختيار هم شته.“ هغه شل سړى ته يې وفرمائيل چې، ”زۀ تا ته وايم چې پاڅه، او بستره دې واخله او کور ته ځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24005, 'Luke 5:25', 'Luke', 5, 25, '&nbsp;او هغه د هغوئ په وړاندې سمدستى پاڅېدو او هغه بستره چې دے پرې پروت وو، يې واخسته او کور ته روان شو او د خُدائ پاک ثنا يې ووئيله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24006, 'Luke 5:26', 'Luke', 5, 26, '&nbsp;هغوئ ټول سخت حېران شول او د خُدائ پاک ثنا يې ووئيله او يرې واخستل او وې وئيل چې، ”نن مونږ څۀ عجيبه کارونه وليدل.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24007, 'Luke 5:27', 'Luke', 5, 27, '&nbsp;وروستو چې بيا عيسىٰ بهر لاړو نو هغۀ ليوى نومې يو محصولچى وليدو چې د محصُول په کُرسۍ ناست وو او هغۀ ته يې وفرمائيل چې، ”ما پسې راځه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24008, 'Luke 5:28', 'Luke', 5, 28, '&nbsp;او هغه پاڅېدو، هر څۀ يې پرېښودل او په هغۀ پسې روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24009, 'Luke 5:29', 'Luke', 5, 29, '&nbsp;بيا وروستو ليوى په خپل کور کښې د عيسىٰ لويه مېلمستيا وکړله. په دې مېلمنو کښې ګڼ محصولچيان او نور خلق هم شريک وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24010, 'Luke 5:30', 'Luke', 5, 30, '&nbsp;فريسيانو او د هغوئ د فرقې د شرعې عالمانو د عيسىٰ مريدانو ته دا ګيله وکړله چې، ”تاسو د محصولچيانو او ګناهګارو سره ولې يو ځائ روټۍ خورئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24011, 'Luke 5:31', 'Luke', 5, 31, '&nbsp;عيسىٰ هغوئ ته جواب ورکړو چې، ”روغو خلقو ته د طبيب حاجت نۀ وى خو بيمارانو ته يې وى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24012, 'Luke 5:32', 'Luke', 5, 32, '&nbsp;زۀ د دې دپاره نۀ يم راغلے چې صادقانو ته دعوت ورکړم بلکې د ګناهګارو دپاره چې توبه وکړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24013, 'Luke 5:33', 'Luke', 5, 33, '&nbsp;بيا هغوئ عيسىٰ ته وفرمائيل چې، ”د يحيىٰ مريدان خو روژې نيسى او عبادتونه کوى او دغه شان د فريسيانو مريدان هم، خو ستا مريدان خورى څښى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24014, 'Luke 5:34', 'Luke', 5, 34, '&nbsp;عيسىٰ جواب ورکړو، ”ولې تاسو په جنجيانو هغه وخت روژه نيولے شئ کوم وخت چې زلمے د هغوئ سره وى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24015, 'Luke 5:35', 'Luke', 5, 35, '&nbsp;خو يو وخت به راشى چې زلمے به د دوئ نه بوتلے شى او دغه وخت به دوئ روژې نيسى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24016, 'Luke 5:36', 'Luke', 5, 36, '&nbsp;عيسىٰ هغوئ ته دا مِثال هم وفرمائيلو چې، ”هيڅوک هم د نوې چُوغې نه د دې دپاره ټوټه نۀ شلوى چې زړه پرې پيوند کړى. کۀ چرې هغه داسې وکړى نو هغه به په نوې چُوغې کښې سورے وکړى او دا نوې ټوکړه به د زړې سره هيڅ سمون ونۀ خورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24017, 'Luke 5:37', 'Luke', 5, 37, '&nbsp;او څوک هم نوى مے په زړو مشکونو کښې نۀ اچوى، ګنې نو نوى مے به مشکونه وشلوى او مے به ضائع شى او مشکونه به تباه شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24018, 'Luke 5:38', 'Luke', 5, 38, '&nbsp;نو په کار دى چې نوى مے په نوؤ مشکونو کښې واچولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24019, 'Luke 5:39', 'Luke', 5, 39, '&nbsp;او هر چا چې زاړۀ مے څښلى وى د نوؤ ميو خواهش به نۀ کوى، ځکه چې هغه وائى چې زاړۀ ښۀ دى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24020, 'Luke 6:1', 'Luke', 6, 1, '&nbsp;نو يو ځل د سبت په ورځ عيسىٰ د فصل په پټو تېرېدو او د هغۀ مريدانو وَږى شوکول، هغه يې په لاسونو کښې مږل او خوړل يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24021, 'Luke 6:2', 'Luke', 6, 2, '&nbsp;ځينو فريسيانو دا ووئيل چې، ”تاسو هغه کار ولې کوئ کوم چې د سبت په ورځ ناروا وى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24022, 'Luke 6:3', 'Luke', 6, 3, '&nbsp;عيسىٰ ورله جواب ورکړو، ”تاسو دا نۀ دى لوستلى کله چې داؤد او د هغۀ دوستان اوږى وُو نو هغوئ څۀ وکړل؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24023, 'Luke 6:4', 'Luke', 6, 4, '&nbsp;هغه د خُدائ پاک کور ته ننوتو او پېش کړے شوې روټۍ يې راواخسته او وې خوړه، اګر چې هغه په دۀ او د دۀ په ملګرو ناروا وه او صرف اِمامانو ته روا وه. او هغۀ څۀ خپلو دوستانو له هم ورکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24024, 'Luke 6:5', 'Luke', 6, 5, '&nbsp;بيا هغۀ دا وفرمائيل چې، ”اِبن آدم د سبت د ورځې مالِک دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24025, 'Luke 6:6', 'Luke', 6, 6, '&nbsp;د يو بل سبت په ورځ عيسىٰ عبادتخانې ته ننوتو او تعليم يې ورکولو. هلته په ګڼه کښې يو سړے وو چې ښے لاس يې اوچ شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24026, 'Luke 6:7', 'Luke', 6, 7, '&nbsp;او د شرعې عالمانو او فريسيانو دې ته کتل چې عيسىٰ به د سبت په ورځ دے روغ کړى او کۀ نه؟ د دې دپاره چې په هغۀ باندې د هغۀ خلاف څۀ اِلزام ولګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24027, 'Luke 6:8', 'Luke', 6, 8, '&nbsp;خو هغه پوهېدو چې د دوئ په زړونو کښې څۀ دى. نو هغۀ هغه سړى ته چې لاس يې وُچ وو، وفرمائيل چې، ”پاڅه او دلته ودرېږه.“ نو هغه پاڅېدو او هلته ودرېدلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24028, 'Luke 6:9', 'Luke', 6, 9, '&nbsp;عيسىٰ بيا هغوئ ته وفرمائيل چې، ”تاسو راته دا ووايئ چې د سبت په ورځ نېکى کول روا دى کۀ بد، ژوند بچ کول کۀ تباه کول؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24029, 'Luke 6:10', 'Luke', 6, 10, '&nbsp;هغۀ ټولو ته ګېرچاپېره وکتل او بيا يې هغه سړى ته وفرمائيل چې، ”خپل لاس اوږد کړه.“ نو هغۀ داسې وکړل او د هغۀ لاس روغ جوړ شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24030, 'Luke 6:11', 'Luke', 6, 11, '&nbsp;خو هغوئ د غصې نه سرۀ شول او يو بل ته يې ووئيل چې، ”مونږ د عيسىٰ سره څۀ وکړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24031, 'Luke 6:12', 'Luke', 6, 12, '&nbsp;هم په دغه ورځو کښې عيسىٰ غرونو ته لاړو چې دُعا وکړى او ټوله شپه يې د خُدائ پاک نه دُعا وغوښتله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24032, 'Luke 6:13', 'Luke', 6, 13, '&nbsp;چې سحر شو نو هغۀ خپل مريدان راوبلل او د هغوئ نه يې دولس کسان خوښ کړل او هغوئ يې رسولان وبلل:', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24033, 'Luke 6:14', 'Luke', 6, 14, '&nbsp;شمعون په چا چې هغۀ پطروس نوم کېښودو، او د هغۀ ورور اندرياس، يعقوب، يوحنا، فيليپوس، برتلماۍ،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24034, 'Luke 6:15', 'Luke', 6, 15, '&nbsp;متى، توما، د حلفئ زوئ يعقوب، او شمعون چې ورته ننګيالے هم وئيلے شى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24035, 'Luke 6:16', 'Luke', 6, 16, '&nbsp;او د يعقوب زوئ يهوداه، او يهوداه اِسکريوتى چا چې وروستو د هغۀ جاسوسى وکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24036, 'Luke 6:17', 'Luke', 6, 17, '&nbsp;عيسىٰ د هغوئ سره د غرۀ نه راکوز شو او په هوار مېدان کښې ودرېدو. په دغه ځائ کښې د هغۀ د مريدانو ډله او ډېر خلق، چې ټول د يهوديه او يروشلم او د صور او د صيدا د سمندرى غاړې نه راټول شوى وُو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24037, 'Luke 6:18', 'Luke', 6, 18, '&nbsp;او د هغۀ اورېدو ته راغلى وُو او چې دوئ د خپلو رنځونو نه شفا ومومى. او هغه څوک چې پيريانو نيولى وُو، روغ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24038, 'Luke 6:19', 'Luke', 6, 19, '&nbsp;ټولو خلقو کوشش کولو چې لاس وروړى ځکه چې د هغۀ نه يو طاقت راوتلو او ټول به يې روغول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24039, 'Luke 6:20', 'Luke', 6, 20, '&nbsp;بيا عيسىٰ خپلو مريدانو ته مخ راواړولو او وې فرمائيل چې، ”تاسو بختور يئ چې غريبان يئ، ځکه چې د خُدائ پاک بادشاهى ستاسو ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24040, 'Luke 6:21', 'Luke', 6, 21, '&nbsp;تاسو بختور يئ چې اوږى يئ، ستاسو لوږه به په مړېدو بدله شى. تاسو بختور يئ چې اوس ژاړئ، ستاسو ژړا به په خندا بدله شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24041, 'Luke 6:22', 'Luke', 6, 22, '&nbsp;تاسو بختور يئ کله چې خلق تاسو نه نفرت کوى او د خپل مينځ نه مو شړى او درته سپکې سپورې وائى او د اِبن آدم د مريدى په وجه په تاسو اِلزام لګوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24042, 'Luke 6:23', 'Luke', 6, 23, '&nbsp;نو په هغه ورځ تاسو خوشحالى کوئ او په خوشحالى ټوپونه وهئ ځکه چې په آسمان کښې ستاسو دپاره لوئ اجر دے. هم دغه شان د دوئ پلار نيکونو هم د نبيانو سره دغه شان سلوک کړے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24043, 'Luke 6:24', 'Luke', 6, 24, '&nbsp;خو اے مالدارو. په تاسو افسوس دے ځکه چې تاسو خپل د خوشحالۍ دور تير کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24044, 'Luke 6:25', 'Luke', 6, 25, '&nbsp;په تاسو افسوس چې اوس ماړۀ يئ ځکه چې تاسو به اوږى شئ. په تاسو افسوس چې اوس خاندئ، ځکه چې تاسو به په غم آخته شئ او ژاړئ به.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24045, 'Luke 6:26', 'Luke', 6, 26, '&nbsp;افسوس دے په تاسو کله چې ټول خلق ستاسو ښۀ تعريف کوى نو دغه شان د هغوئ پلار نيکونو د دروغژنو نبيانو تعريف هم کولو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24046, 'Luke 6:27', 'Luke', 6, 27, '&nbsp;خو ما ته غوږ شئ چې زۀ درته څۀ وايم د خپلو دشمنانو سره مينه کوئ او څوک چې ستاسو نه نفرت کوى د هغوئ سره ښۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24047, 'Luke 6:28', 'Luke', 6, 28, '&nbsp;د هغوئ دپاره برکت غواړئ څوک چې په تاسو لعنت کوى او د هغوئ دپاره دُعا کوئ څوک چې تاسو بې‌عزته کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24048, 'Luke 6:29', 'Luke', 6, 29, '&nbsp;کۀ څوک تاسو په يو مخ ووهى نو هغۀ ته بل مخ هم ورواړوئ. کۀ څوک ستاسو چُوغه واخلى نو هغۀ ته خپل قميص هم ورکړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24049, 'Luke 6:30', 'Luke', 6, 30, '&nbsp;څوک هم چې ستاسو نه څۀ وغواړى هغوئ له يې ورکړئ. کله چې تاسو نه څوک هم ستاسو څيز واخلى نو د هغۀ نه يې بيا تپوس مۀ کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24050, 'Luke 6:31', 'Luke', 6, 31, '&nbsp;د نورو سره داسې سلوک کوئ لکه څنګه سلوک چې تاسو د ځان دپاره غواړئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24051, 'Luke 6:32', 'Luke', 6, 32, '&nbsp;کۀ تاسو صرف د هغوئ سره مينه کوئ څوک چې تاسو سره مينه کوى نو بيا تاسو د کوم اجر اُميدوار يئ؟ ځکه چې ګناه ګار هم د هغه چا سره مينه کوى څوک چې د هغوئ سره مينه کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24052, 'Luke 6:33', 'Luke', 6, 33, '&nbsp;او کۀ چرې تاسو د هغه چا سره نېکى کوئ څوک چې تاسو سره ښېګړه کوى نو ستاسو څۀ اجر دے؟ ځکه چې ګناه ګار خو هم دغسې کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24053, 'Luke 6:34', 'Luke', 6, 34, '&nbsp;او کۀ چرې تاسو تش هغه چا له قرض ورکوئ چې ستاسو باور وى چې تاسو ته به يې واپس کړى نو په دې کښې ستاسو اجر څۀ دے؟ ځکه چې ګناه ګار هم يو بل له قرض ورکوى او يو بل ته يې پوره واپس کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24054, 'Luke 6:35', 'Luke', 6, 35, '&nbsp;خو تاسو د خپلو دشمنانو سره مينه او نېکى کوئ او قرض بغېر د څۀ لالچه ورکوئ. نو تاسو به ډېر لوئ اجر ومومئ. تاسو به بيا د خُدائ تعالىٰ زامن شئ ځکه چې هغه په خپله هم په ناشُکرو او په شريرانو مهربانه دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24055, 'Luke 6:36', 'Luke', 6, 36, '&nbsp;ترس ناک شئ لکه څنګه چې ستاسو پلار هم ترس ناک دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24056, 'Luke 6:37', 'Luke', 6, 37, '&nbsp;په نورو اِلزام مۀ لګوئ نو په تاسو به هم اِلزام ونۀ لګولے شى. بل څوک مۀ مجرموئ نو تاسو به هم مجرم ونۀ ګڼلے شئ. معاف کوئ نو تاسو به هم معاف کړے شئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24057, 'Luke 6:38', 'Luke', 6, 38, '&nbsp;ورکړئ، نو تاسو ته به واپس درکړے شى. نو ستاسو جولۍ ته به ستاسو برخه ښۀ منډلې دربلې ښۀ ډکه تر خولې خولې واپس مِلاو شى. نو چې څنګه تاسو د بل ناپ تول کوئ دغه رنګ به واپس ستاسو ناپ تول کولے شى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24058, 'Luke 6:39', 'Luke', 6, 39, '&nbsp;او عيسىٰ هغوئ ته يو مِثال هم وئيلو چې، ”ولې يو ړوند بل ړوند ته لار ښودلے شى څۀ؟ آيا دواړه به په کنده کښې ونۀ غورزيږى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24059, 'Luke 6:40', 'Luke', 6, 40, '&nbsp;شاګرد د خپل اُستاذ نه لوئ نۀ وى خو هر هغه څوک چې پوره تربيت حاصل کړى نو هغه به د خپل اُستاذ په شان شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24060, 'Luke 6:41', 'Luke', 6, 41, '&nbsp;تاسو د خپل ورور د سترګې خسڼى ته ولې ګوته نيسئ خو په خپله سترګه کښې درته تير نۀ ښکارى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24061, 'Luke 6:42', 'Luke', 6, 42, '&nbsp;تۀ څنګه خپل ورور ته دا وئيلے شې چې، وروره، راشه چې ستا د سترګې نه دا خسڼے وباسم، خو حال دا چې په خپله سترګه کښې درته تير نۀ ښکارى؟ اے رياکاره، اول د خپلې سترګې نه تير وباسه، نو بيا به ستا سترګې وغړيږى چې د خپل ورور د سترګې نه خسڼے وباسې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24062, 'Luke 6:43', 'Luke', 6, 43, '&nbsp;هيڅکله ښۀ ونه بده مېوه نۀ نيسى، او هيڅکله بده ونه ښۀ مېوه نۀ نيسى،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24063, 'Luke 6:44', 'Luke', 6, 44, '&nbsp;ځکه چې هره ونه په خپلې مېوې پېژندلے کيږى. تۀ د ازغو بوټو نه اينځر نۀ شې راټولولے او نۀ د جاړو بوټو نه انګور راشوکولے شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24064, 'Luke 6:45', 'Luke', 6, 45, '&nbsp;ښۀ سړے به د خپل زړۀ د خزانې نه ښۀ څيزونه راوباسى او بد سړے به د خپل زړۀ د بدې خزانې نه بدې خبرې وباسى، ځکه چې کومې خبرې چې په خولۀ راځى هغه د زړۀ نه راوځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24065, 'Luke 6:46', 'Luke', 6, 46, '&nbsp;تاسو ما ته ولې مالِک مالِک وايئ او هغه کار هيڅکله هم نۀ کوئ چې زۀ يې درته وايم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24066, 'Luke 6:47', 'Luke', 6, 47, '&nbsp;هر هغه څوک چې ما له راځى او زما خبرې اورى او عمل پرې کوى نو زۀ به تاسو ته وښايم چې هغه د چا په شان دے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24067, 'Luke 6:48', 'Luke', 6, 48, '&nbsp;هغه د يو داسې سړى په شان دے چا چې د کور جوړولو دپاره ښۀ ژور بنيادونه وکنستل او بنياد يې په پوخ ګټ کېښودلو. او هر کله چې سېلاب راغلو نو په کور وروختو خو هغه يې ونۀ خوځولے شو ځکه چې هغه پوخ جوړ شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24068, 'Luke 6:49', 'Luke', 6, 49, '&nbsp;خو څوک چې زما خبرې اورى او عمل پرې نۀ کوى نو هغه د داسې سړى په شان دے چا چې د خپل کور بنياد د زمکې په مخ جوړ کړو. کله چې سېلاب راغلو نو په کور وروختو نو هغه يې راوغورزولو او بلکل تباه يې کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24069, 'Luke 7:1', 'Luke', 7, 1, '&nbsp;کله چې يې ټولې خبرې خلقو ته خلاصې کړې نو عيسىٰ کفرنحُوم ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24070, 'Luke 7:2', 'Luke', 7, 2, '&nbsp;هلته د صوبه دار يو نوکر وو کوم چې په هغۀ ډېر ګران وو. او هغه مرګى حال پروت وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24071, 'Luke 7:3', 'Luke', 7, 3, '&nbsp;نو کله چې صوبه دار د عيسىٰ په حقله واورېدل نو هغۀ يو څو يهوديان مشران ورولېږل او خواست يې ورته وکړو چې هغه راشى او د هغۀ نوکر له شفا ورکړى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24072, 'Luke 7:4', 'Luke', 7, 4, '&nbsp;هغوئ عيسىٰ له راغلل او ډېر زارى مِنت يې ورته وکړو او ورته يې ووئيل چې، ”صوبه دار ستا د مدد حقدار دے،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24073, 'Luke 7:5', 'Luke', 7, 5, '&nbsp;ځکه چې هغه زمونږ د قوم خوږمن دے او هغۀ زمونږ دپاره عبادتخانه هم جوړه کړې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24074, 'Luke 7:6', 'Luke', 7, 6, '&nbsp;عيسىٰ د هغوئ سره لاړو. نو چې هغه کور ته نزدې شو نو صوبه دار يو څو دوستان په دې غرض ورولېږل چې، ”مالِکه، نور تکليف مۀ کوه ځکه چې زۀ د دې جوګه نۀ يم چې تۀ زما کور ته راشې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24075, 'Luke 7:7', 'Luke', 7, 7, '&nbsp;زۀ په خپله خو څۀ هم نۀ يم نو په دې وجه زۀ تاسو ته حاضر نۀ شوم. خو کۀ تاسو صرف حکم وکړئ نو زما نوکر به جوړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24076, 'Luke 7:8', 'Luke', 7, 8, '&nbsp;ځکه چې زۀ پوهېږم چې زۀ په خپله د بل د حکم لاندې يم او سپاهيان زما د حکم لاندې دى. زۀ چې يو ته ووايم چې لاړ شه نو هغه لاړ شى، او چې بل ته ووايم چې دېخوا راشه، نو هغه راشى او چې خپل غلام ته ووايم چې داسې وکړه نو هغه يې هغه شان کوى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24077, 'Luke 7:9', 'Luke', 7, 9, '&nbsp;کله چې عيسىٰ دا واورېدل نو د هغۀ ايمان ته حېران شو، نو هغۀ ګڼې ته وفرمائيل چې، ”زۀ تاسو ته دا وايم چې ما داسې ايمان په بنى اِسرائيلو کښې چرته هم نۀ دے ليدلے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24078, 'Luke 7:10', 'Luke', 7, 10, '&nbsp;او هغه مشران چې کور ته واپس راغلل نو هغوئ هغه نوکر روغ جوړ وليدو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24079, 'Luke 7:11', 'Luke', 7, 11, '&nbsp;پس له هغې عيسىٰ نائن نومې ښاريې ته لاړو. د هغۀ سره خپل مريدان او نور ګڼ خلق هم ورسره وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24080, 'Luke 7:12', 'Luke', 7, 12, '&nbsp;کله چې هغه د ښاريې دروازې ته ورسېدلو نو يوه جنازه يې وليده. دغه جنازه د يوې کونډې د يک يو زوئ وه او د دې سره د ښاريې ګڼ خلق وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24081, 'Luke 7:13', 'Luke', 7, 13, '&nbsp;کله چې مالِک عيسىٰ هغه وليدله نو زړۀ يې پرې وسوزېدلو او وې فرمائيل، ”بس نوره مۀ ژاړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24082, 'Luke 7:14', 'Luke', 7, 14, '&nbsp;د دې سره هغه وروړاندې شو او د جنازې په کټ يې لاس کېښودلو او جنازه وړُونکى ودرېدل. بيا هغۀ وفرمائيل چې، ”راپاڅه اے زلميه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24083, 'Luke 7:15', 'Luke', 7, 15, '&nbsp;هغه مړے کښېناستو او په خبرو يې شروع وکړه او عيسىٰ هغه خپلې مور ته بيا حواله کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24084, 'Luke 7:16', 'Luke', 7, 16, '&nbsp;په هغه ټولو خلقو باندې زبردسته يره خوره شوله او هغوئ ټولو د خُدائ پاک ثنا ووئيله او وې وئيل چې، ”زمونږ په مينځ کښې يو لوئ نبى راښکاره شوے دے او خُدائ پاک د خپلو خلقو د مدد دپاره راغلے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24085, 'Luke 7:17', 'Luke', 7, 17, '&nbsp;عيسىٰ چې څۀ کړى وُو هغه قيصه د يهوديه په ټوله علاقه او خوا او شا کښې خوره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24086, 'Luke 7:18', 'Luke', 7, 18, '&nbsp;د يحيىٰ مريدانو هغه په دې هر څۀ خبر کړو. هغۀ خپل دوه مريدان راوغوښتل', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24087, 'Luke 7:19', 'Luke', 7, 19, '&nbsp;او مالِک له يې ولېږل چې تپوس وکړى چې، ”تۀ هغه راتلونکے يې يا دا چې مونږ د بل چا اِنتظار وکړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24088, 'Luke 7:20', 'Luke', 7, 20, '&nbsp;هغه پېغام وړُونکى عيسىٰ له لاړل او ورته يې ووئيل، ”بپتسمه ورکوونکى يحيىٰ مونږ تا له رالېږلى يُو چې تپوس وکړو چې تۀ هغه راتلونکے يې کۀ مونږ د بل چا اِنتظار وکړو؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24089, 'Luke 7:21', 'Luke', 7, 21, '&nbsp;هم په هغه ساعت عيسىٰ ډېرو خلقو ته د بيماريانو نه شفا ورکړله، طاعون او بد پيريان يې لرې کړل او ډېرو ړندو له يې بينائى ورکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24090, 'Luke 7:22', 'Luke', 7, 22, '&nbsp;بيا هغۀ هغه مريدانو ته جواب ورکړو چې، ”لاړ شئ او هر څۀ چې تاسو اورئ او ګورئ هغه يحيىٰ ته ووايئ چې ړاندۀ بينا کيږى، شل ګرځى، جذاميان پاکيږى، کاڼۀ اورى، مړى بيا ژوندى کيږى او غريبانان ښۀ زيرے اورى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24091, 'Luke 7:23', 'Luke', 7, 23, '&nbsp;او بختور دى هغه څوک چې ما نۀ ازاروى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24092, 'Luke 7:24', 'Luke', 7, 24, '&nbsp;کله چې د يحيىٰ مريدان رُخصت شول نو عيسىٰ د هغۀ په حقله خلقو ته وفرمائيل چې، ”تاسو د څۀ ليدلو دپاره بيابان ته تلى وئ؟ يوه لوخه چې باد خوځوله څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24093, 'Luke 7:25', 'Luke', 7, 25, '&nbsp;نو بيا تاسو د څۀ ليدو له وتلى وئ؟ يو کس چې قيمتى جامې يې اچولې وې؟ ګورئ، د چا چې قيمتى لباس وى او عېش عشرت کوى هغوئ په محلونو کښې ژوند کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24094, 'Luke 7:26', 'Luke', 7, 26, '&nbsp;نو بيا تاسو بهر د څۀ ليدو له وتلى وئ؟ يو نبى ليدو له؟ آو، زۀ دا وايم چې د يو نبى نه هم ډېر لوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24095, 'Luke 7:27', 'Luke', 7, 27, '&nbsp;دا هغه څوک دے چې د چا په حقله چې ليکلے شوى دى چې، ”ګوره، زۀ خپل پېغمبر ستا نه وړاندې لېږم چې ستا مخې ته لاره تياره کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24096, 'Luke 7:28', 'Luke', 7, 28, '&nbsp;زۀ تاسو ته وايم د زمکې په مخ بل څوک د يحيىٰ نه لوئ نشته خو بيا هم د خُدائ پاک په بادشاهۍ کښې د ټولو نه کمزورے کس د هغۀ نه لوئ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24097, 'Luke 7:29', 'Luke', 7, 29, '&nbsp;او ټولو خلقو چا چې د عيسىٰ خبرې واورېدلې نو سره د محصولچيانو يې د خُدائ پاک لار سمه وګڼله ځکه چې د يحيىٰ نه يې بپتسمه اخستې وه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24098, 'Luke 7:30', 'Luke', 7, 30, '&nbsp;خو بې د فريسيانو او د شرعې د عالمانو نه چا چې د هغۀ د بپتسمې نه اِنکار کړے وو او د ځان دپاره يې د خُدائ پاک د حُکم نه مخ اړولے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24099, 'Luke 7:31', 'Luke', 7, 31, '&nbsp;”د دې پيړۍ د خلقو مِثال په څۀ درکړم؟ هغوئ د چا په شان دى؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(24100, 'Luke 7:32', 'Luke', 7, 32, '&nbsp;هغوئ په بازار کښې د ناستو ماشومانو په شان دى څوک چې يو بل ته چغې وهى او وائى چې، مونږ تاسو ته شپيلۍ وغږولې او تاسو ګډا ونۀ کړه. مونږ ژړا انګولا وکړه او تاسو وير ونۀ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');